// The About window: version, Gestalt's license and every
// third-party package and piece of content it ships, with license texts.
// The inventory is generated by scripts/licenses.mjs. Esc closes the window.

import { getVersion } from "@tauri-apps/api/app";
import { getCurrentWindow } from "@tauri-apps/api/window";
import { openUrl } from "@tauri-apps/plugin-opener";
import icon from "../src-tauri/icons/128x128@2x.png";
import { initSystemColors } from "./systemColors";

/** Shape of public/third-party-licenses.json (scripts/licenses.mjs). */
interface Inventory {
  gestalt: { name: string; license: string; copyright: string; text: string };
  summary: Record<string, number>;
  packages: Pkg[];
  texts: Record<string, string>;
}
interface Pkg {
  ecosystem: "cargo" | "npm" | "content";
  name: string;
  version: string;
  declared: string;
  url: string;
  note?: string;
  licenses: string[];
  texts: string[];
}

type Tab = "about" | "license" | "third-party";
const ECOSYSTEM: Record<Pkg["ecosystem"], string> = { cargo: "Rust", npm: "npm", content: "Content" };

const h = <K extends keyof HTMLElementTagNameMap>(
  tag: K,
  props: Partial<HTMLElementTagNameMap[K]> & { class?: string } = {},
  ...children: (Node | string)[]
): HTMLElementTagNameMap[K] => {
  const el = document.createElement(tag);
  const { class: cls, ...rest } = props;
  Object.assign(el, rest);
  if (cls) el.className = cls;
  el.append(...children);
  return el;
};

/** A link that opens in the system browser, never inside the webview. */
const link = (href: string, text: string = href) =>
  h("a", {
    href,
    onclick: (e: MouseEvent) => {
      e.preventDefault();
      void openUrl(href);
    },
  }, text);

/** An in-window action styled as a link. */
const action = (text: string, run: () => void) =>
  h("a", {
    href: "#",
    onclick: (e: MouseEvent) => {
      e.preventDefault();
      run();
    },
  }, text);

// ---- State ------------------------------------------------------------------

let inv: Inventory | null = null;
let error: string | null = null;
let version = "";
let tab: Tab = "about";

const nav = h("nav", { class: "about-tabs" });
const body = h("div", { class: "about-body" });
document.body.append(h("header", { class: "about-head" }, nav), body);

function render() {
  const tabs: [Tab, string][] = [
    ["about", "About"],
    ["license", "License"],
    ["third-party", `Third-party software${inv ? ` (${inv.packages.length})` : ""}`],
  ];
  nav.replaceChildren(
    ...tabs.map(([id, label]) =>
      h("button", { class: tab === id ? "active" : "", onclick: () => show(id) }, label),
    ),
  );

  body.replaceChildren();
  if (error) body.append(h("p", { class: "error" }, error));
  if (tab === "about") body.append(aboutTab());
  else if (tab === "license" && inv) body.append(h("pre", { class: "license-text" }, inv.gestalt.text));
  else if (tab === "third-party" && inv) body.append(thirdParty(inv));
}

function show(next: Tab) {
  tab = next;
  body.scrollTop = 0;
  render();
}

// ---- About tab ----------------------------------------------------------------

function aboutTab(): HTMLElement {
  const credits = inv?.packages.filter((p) => p.ecosystem === "content") ?? [];
  const count = inv ? inv.packages.length - credits.length : null;
  const main = h(
    "div",
    { class: "about-main" },
    h("img", { src: icon, alt: "", width: 96, height: 96 }),
    h("h1", {}, "Gestalt"),
    h("p", { class: "muted" }, version && `Version ${version}`),
    h("p", {}, "Run OpenTofu plans and applies across a folder tree of modules."),
    h(
      "p",
      { class: "muted" },
      `${inv?.gestalt.copyright ?? "Copyright (c) 2026 it-problems"}. Released under the MIT License.`,
    ),
    h("p", {}, action("Third-party licenses", () => show("third-party"))),
  );
  const section = h(
    "section",
    { class: "credits" },
    h("h3", {}, "Built on"),
    ...credits.map((c) =>
      h("p", {}, link(c.url, c.name), ` (${c.licenses.join(", ")}). ${c.note ?? ""}`),
    ),
    h(
      "p",
      {},
      "Built with ",
      link("https://tauri.app", "Tauri"),
      " and ",
      link("https://opentofu.org", "OpenTofu"),
      `, and ${count ?? "many"} open-source packages.`,
    ),
  );
  main.append(section);
  return main;
}

// ---- Third-party tab ----------------------------------------------------------

/** Survives re-renders so switching tabs keeps the search. */
const filter = { query: "", license: null as string | null, open: null as string | null };

function thirdParty(inv: Inventory): HTMLElement {
  const list = h("ul", { class: "packages" });
  const chips = h("div", { class: "chips" });
  const search = h("input", {
    type: "search",
    placeholder: "Search packages",
    value: filter.query,
    spellcheck: false,
    oninput: () => {
      filter.query = search.value;
      update();
    },
  });

  const chip = (label: string, license: string | null) =>
    h(
      "button",
      {
        class: `chip ${filter.license === license ? "on" : ""}`,
        // Clicking the chosen license again clears the filter.
        onclick: () => {
          filter.license = filter.license === license ? null : license;
          update();
        },
      },
      label,
    );

  function row(p: Pkg): HTMLElement {
    const key = `${p.ecosystem}:${p.name}@${p.version}`;
    const expanded = filter.open === key;
    const li = h(
      "li",
      { class: expanded ? "open" : "" },
      h(
        "button",
        {
          class: "pkg",
          onclick: () => {
            filter.open = expanded ? null : key;
            update();
          },
        },
        h("span", { class: "pkg-name" }, p.name),
        h("span", { class: "pkg-version" }, p.version),
        h("span", { class: "eco" }, ECOSYSTEM[p.ecosystem]),
        h("span", { class: "pkg-license" }, p.licenses.join(", ")),
      ),
    );
    if (expanded) {
      const head = h("p", {}, link(p.url));
      if (p.declared !== p.licenses.join(", ")) head.append(h("span", { class: "muted" }, ` · declared: ${p.declared}`));
      const detail = h("div", { class: "pkg-detail" }, head);
      if (p.note) detail.append(h("p", {}, p.note));
      if (p.texts.length === 0) detail.append(h("p", { class: "muted" }, "The package ships no license file."));
      for (const t of p.texts) detail.append(h("pre", { class: "license-text" }, inv.texts[t]));
      li.append(detail);
    }
    return li;
  }

  function update() {
    chips.replaceChildren(
      chip(`All ${inv.packages.length}`, null),
      ...Object.entries(inv.summary).map(([l, n]) => chip(`${l} ${n}`, l)),
    );
    const q = filter.query.trim().toLowerCase();
    const rows = inv.packages.filter(
      (p) => (!filter.license || p.licenses.includes(filter.license)) && (!q || p.name.toLowerCase().includes(q)),
    );
    list.replaceChildren(...rows.map(row));
    if (rows.length === 0) list.append(h("li", { class: "muted empty" }, "No matching packages"));
  }

  update();
  return h(
    "div",
    { class: "third-party" },
    h(
      "p",
      { class: "muted" },
      "Gestalt includes the software and content below, each under its own license. Where a package offers a choice, the license Gestalt uses is listed first.",
    ),
    h("div", { class: "filters" }, search, chips),
    list,
  );
}

// ---- Startup ------------------------------------------------------------------

window.addEventListener("keydown", (e) => {
  if (e.key === "Escape") void getCurrentWindow().close();
});

initSystemColors();
render();

getVersion()
  .then((v) => {
    version = v;
    render();
  })
  .catch(() => {});
fetch("/third-party-licenses.json")
  .then((r) => {
    if (!r.ok) throw new Error(`License inventory missing (${r.status}). Run: node scripts/licenses.mjs`);
    return r.json() as Promise<Inventory>;
  })
  .then(
    (data) => {
      inv = data;
      render();
    },
    (e) => {
      error = String(e);
      render();
    },
  );
